-- Check the relationship between sensor data, containers, and transport info
-- Also check alerttime range for "recent period" (last 3 months)
SELECT MIN(alerttime), MAX(alerttime) FROM sensordata WHERE alerttime IS NOT NULL;

-- Let me check what the current date context is and try using CURRENT_DATE

-- Check max alerttime vs current_date
SELECT MAX(alerttime), CURRENT_DATE, CURRENT_DATE - INTERVAL '3 months' FROM sensordata;

-- Both paths give 900 records. Let me check if they give the same vehicles
SELECT COUNT(DISTINCT ti1.vehiclereg) FROM sensordata sd JOIN transportinfo ti ON sd.vehsenseref = ti.vehiclereg;
SELECT COUNT(DISTINCT ti2.vehiclereg) FROM sensordata sd JOIN container c ON sd.containlink = c.containregistry JOIN shipments s ON c.shipown = s.shipmentregistry JOIN transportinfo ti ON s.shipmentregistry = ti.shiptransit;

-- Both paths give 900 distinct vehicles. Let me check if the transmode values match
SELECT DISTINCT ti.transmode FROM sensordata sd JOIN transportinfo ti ON sd.vehsenseref = ti.vehiclereg;
SELECT DISTINCT ti2.transmode FROM sensordata sd JOIN container c ON sd.containlink = c.containregistry JOIN shipments s ON c.shipown = s.shipmentregistry JOIN transportinfo ti2 ON s.shipmentregistry = ti2.shiptransit;

-- If recent period is CURRENT_DATE - INTERVAL '3 months', that's 2026-02-16
-- But all alerttime values are around 2025-02-18 to 2025-02-19
-- So no records would match with CURRENT_DATE filter

-- Let me check if maybe the data has more recent entries I'm missing
SELECT MAX(alerttime) FROM sensordata;
SELECT COUNT(*) FROM sensordata WHERE alerttime IS NOT NULL;
